INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l58','a blessing in disguise','',NULL,'/ə ˈblesɪŋ ɪn dɪsˈɡaɪz/','The delay was a blessing in disguise.','这次延误因祸得福。','Losing that job was a blessing in disguise.','丢了那份工作反倒是好事。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l58','be said to','',NULL,'/biː sed tuː/','The tree is said to be cursed.','据说这棵树被诅咒了。','He is said to be very rich.','据说他很有钱。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l58','in spite of','',NULL,'/ɪn spaɪt əv/','In spite of the warning, tourists came.','尽管有警告,游客还是来了。','He went out in spite of the rain.','尽管下雨他还是出门了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l58','so far','',NULL,'/soʊ fɑːr/','So far, no one has been hurt.','到目前为止没人受伤。','So far so good.','到目前为止一切顺利。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp1','choice','{"stem":"\"The tree ___ planted near the church fifty years ago.\"(过去被动:被种植)","options":["were","has","was","is"],"answer_index":2,"stem_cn":"这棵树是 50 年前栽在教堂附近的。","explanation_cn":"过去被动 = was/were + 过去分词;主语 tree 单数用 was planted。✓ The tree was planted near the church fifty years ago. ✗ is:时态应是过去;✗ has:构不成被动;✗ were:主语单数不用 were。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp1','choice','{"stem":"\"I ___ told to wait for him.\"(过去被动:被告知)","options":["did","have","am","was"],"answer_index":3,"stem_cn":"我被通知等等他。","explanation_cn":"过去被动 = was + 过去分词;主语 I 用 was told。✓ I was told to wait for him. ✗ am:时态应是过去;✗ have:构不成被动;✗ did:不构成被动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp1','choice','{"stem":"\"The tree ___ mentioned in a newspaper.\"(过去被动:被提到)","options":["is","were","was","has"],"answer_index":2,"stem_cn":"报上提到过这棵树。","explanation_cn":"过去被动 = was + 过去分词;主语 tree 单数用 was mentioned。✓ The tree was mentioned in a newspaper. ✗ is:时态应是过去;✗ has:构不成被动;✗ were:主语单数不用 were。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp2','choice','{"stem":"\"He ___ sent abroad right now.\"(现在进行被动:正被送出国)","options":["is being","was","is","has been"],"answer_index":0,"stem_cn":"他正被送出国。","explanation_cn":"现在进行被动 = is/are being + 过去分词;\"正被送出国\"用 is being sent。✓ He is being sent abroad right now. ✗ is:少了 being 不表\"正在被\";✗ has been:是完成被动;✗ was:过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp2','choice','{"stem":"\"Your wallet ___ found.\"(现在完成被动:已被找到)","options":["was being","has been","is being","has"],"answer_index":1,"stem_cn":"你的钱包被找到了。","explanation_cn":"现在完成被动 = has/have been + 过去分词;\"已被找到\"用 has been found。✓ Your wallet has been found. ✗ is being:是进行被动;✗ was being:过去进行被动;✗ has:少了 been 不成被动。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp2','choice','{"stem":"\"So far, not one of them ___ struck down by sudden death.\"(现在完成被动:被击倒)","options":["has been","has","was","is being"],"answer_index":0,"stem_cn":"到目前为止,还没有一个人暴死。","explanation_cn":"现在完成被动 = has been + 过去分词;\"(至今)没被击倒\"用 has been struck。✓ not one of them has been struck down. ✗ is being:进行被动;✗ was:过去;✗ has:少了 been。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp3','choice','{"stem":"\"The village ___ said to possess a ''cursed tree''.\"(据说…拥有,be said to do 的 be 动词)","options":["was said","is","has","being"],"answer_index":1,"stem_cn":"据说这个村庄有一棵''该诅咒的树''。","explanation_cn":"be said to do 表\"据说…\";主语 village 单数用 is said to possess。✓ The village is said to possess a ''cursed tree''. ✗ has:构不成 be said to;✗ being:缺限定动词;✗ was said:此处讲现在的普遍说法用 is。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp3','choice','{"stem":"\"It ___ said that if anyone touches the tree, he will have bad luck.\"(据说…,固定句型的 be 动词)","options":["is","was","has","being"],"answer_index":0,"stem_cn":"据说谁要是碰了这棵树就会交厄运。","explanation_cn":"It is said that… 是固定句型,表\"据说…\"。✓ It is said that if anyone touches the tree, he will have bad luck. ✗ has:构不成这个句型;✗ being:缺限定动词;✗ was:此处用现在时。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp3','choice','{"stem":"\"He is ___ to be a genius.\"(据说他是…,被动''被说成'')","options":["say","told","said","saying"],"answer_index":2,"stem_cn":"据说他是个天才。","explanation_cn":"be said to be 表\"据说是…\";此处填过去分词 said(is said to be)。✓ He is said to be a genius. ✗ say:原形;✗ saying:现在分词;✗ told:be told to 是\"被告知去做\",词义不同。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp4','choice','{"stem":"\"I ___ a pen by my teacher yesterday.\"(双宾语变被动:我''被给了''一支笔)","options":["was giving","was given","gave","was gave"],"answer_index":1,"stem_cn":"昨天老师给了我一支笔。","explanation_cn":"双宾语句变被动:间接宾语(me)作主语时,\"我被给了一支笔\"用 I was given a pen。✓ I was given a pen by my teacher yesterday. ✗ was gave:被动要用过去分词 given;✗ gave:是主动;✗ was giving:进行时不合。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp4','choice','{"stem":"\"He ___ the vacant post by the manager.\"(双宾语变被动:他''被给予''那个空职)","options":["was offer","offered","was offering","was offered"],"answer_index":3,"stem_cn":"经理给了他那个空缺职位。","explanation_cn":"双宾语句变被动:间接宾语(him)作主语时,\"他被给予那个空职\"用 He was offered the post。✓ He was offered the vacant post by the manager. ✗ was offer:被动要用过去分词 offered;✗ offered:是主动;✗ was offering:进行时不合。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp5','choice','{"stem":"\"The number of visitors has ___ in recent years.\"(数量''增加、增多'')","options":["grown","gained","increased","earned"],"answer_index":2,"stem_cn":"近年来参观者的数量增加了。","explanation_cn":"表\"数量增加、增多\"用 increase(increased)。✓ The number of visitors has increased. ✗ grown:grow 多指生长、长大;✗ earned:挣(钱);✗ gained:获得(名声等)。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp5','choice','{"stem":"\"He has gone abroad and is ___ a lot of money.\"(''挣、赚''钱)","options":["increasing","earning","gaining","growing"],"answer_index":1,"stem_cn":"他出国了,听说赚了很多钱。","explanation_cn":"表\"挣钱、赚钱\"用 earn(earning)。✓ he is earning a lot of money. ✗ gaining:gain 多指获得名声/优势;✗ increasing:数量增加;✗ growing:生长。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp5','choice','{"stem":"\"The tree has ___ an evil reputation.\"(''获得、得到''名声)","options":["earned","increased","grown","gained"],"answer_index":3,"stem_cn":"这棵树得了个坏名声。","explanation_cn":"表\"获得(名声、名誉)\"用 gain(gained)。✓ The tree has gained an evil reputation. ✗ earned:多指挣钱;✗ increased:数量增加;✗ grown:生长。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp5','choice','{"stem":"\"The tourists have been ___ leaves from the tree.\"(''摘、采''树叶)","options":["picking","cutting","growing","gaining"],"answer_index":0,"stem_cn":"游客们一直在摘树上的叶子。","explanation_cn":"表\"摘、采(树叶、花)\"用 pick(picking)。✓ The tourists have been picking leaves. ✗ cutting:cut 是切、割(cut their names);✗ growing:生长;✗ gaining:获得。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp6','choice','{"stem":"\"The vicar has been asked to have the tree ___ down.\"(have sth done:让树''被砍'')","options":["cuts","to cut","cutting","cut"],"answer_index":3,"stem_cn":"有人请牧师把这棵树砍掉。","explanation_cn":"have sth done 表\"让某物被…(叫别人做)\";此处 the tree 与 cut 是被动关系,用过去分词 cut(cut 的过去分词仍是 cut)。✓ have the tree cut down. ✗ cutting:不表被动;✗ to cut:have sth done 用过去分词;✗ cuts:形式不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp6','choice','{"stem":"\"It is only in recent years ___ it has gained an evil reputation.\"(强调句型 it is … 后面的连接词)","options":["that","which","what","when"],"answer_index":0,"stem_cn":"只是近几年它才得了坏名声。","explanation_cn":"强调句型 It is … that …,被强调部分后用 that 连接。✓ It is only in recent years that it has gained an evil reputation. ✗ when / which / what:强调句固定用 that(此处强调时间也用 that)。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',5,'am2_l58_gp6','choice','{"stem":"\"Losing that job turned out to be a blessing in ___.\"(因祸得福、坏事变好事的固定短语)","options":["danger","trouble","surprise","disguise"],"answer_index":3,"stem_cn":"丢了那份工作结果因祸得福。","explanation_cn":"\"因祸得福、坏事变好事\"是固定短语 a blessing in disguise。✓ Losing that job turned out to be a blessing in disguise. ✗ danger / trouble / surprise:不构成这个固定短语。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',6,NULL,'choice','{"stem":"美语里\"秋天\"常说:","options":["fall","autumn","harvest time","leaf time"],"answer_index":0,"explanation_cn":"美语\"秋天\"常说 fall;英式说 autumn。✓ leaves fall in the fall 秋天落叶。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',6,NULL,'choice','{"stem":"美语里\"钞票\"常说:","options":["note","paper money","bill","cash slip"],"answer_index":2,"explanation_cn":"美语\"钞票\"常说 bill;英式说 note(banknote)。✓ a ten-dollar bill 一张十美元钞票。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',6,NULL,'choice','{"stem":"tiny 的意思是:","options":["巨大的","普通的","古老的","极小的"],"answer_index":3,"explanation_cn":"tiny = 极小的。✓ the tiny village of Frinley 弗林利小村。\n顺带记:巨大的 = huge;普通的 = ordinary;古老的 = ancient."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',6,NULL,'choice','{"stem":"possess 的意思是:","options":["失去","拥有","出售","隐藏"],"answer_index":1,"explanation_cn":"possess = 拥有。✓ said to possess a cursed tree 据说有一棵被诅咒的树。\n顺带记:失去 = lose;出售 = sell;隐藏 = hide."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',6,NULL,'choice','{"stem":"reputation 的意思是:","options":["财富","秘密","习惯","名声,名誉"],"answer_index":3,"explanation_cn":"reputation = 名声、名誉。✓ gained an evil reputation 得了坏名声。\n顺带记:财富 = wealth;秘密 = secret;习惯 = habit."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',6,NULL,'choice','{"stem":"income 的意思是:","options":["支出","收入","礼物","债务"],"answer_index":1,"explanation_cn":"income = 收入。✓ a useful source of income 一个有用的财源。\n顺带记:支出 = expense;债务 = debt;礼物 = gift."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',7,NULL,'cloze','{"stem":"第 1 空","context":"The tiny village of Frinley ___1___ said to possess a ''cursed tree''. The tree ___2___ planted near the church fifty years ago. The vicar ___3___ asked to have it cut down, but he refused. So far, not one tourist ___4___ struck down by sudden death.","blank_no":1,"options":["is","has","was","being"],"answer_index":0,"explanation_cn":"be said to do 表\"据说…\";主语 village 单数用 is said to possess。✓ Frinley is said to possess a ''cursed tree''.\n✗ has:构不成 be said to;✗ was:此处讲现在的说法用 is;✗ being:缺限定动词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',7,NULL,'cloze','{"stem":"第 2 空","context":"The tiny village of Frinley ___1___ said to possess a ''cursed tree''. The tree ___2___ planted near the church fifty years ago. The vicar ___3___ asked to have it cut down, but he refused. So far, not one tourist ___4___ struck down by sudden death.","blank_no":2,"options":["was","is","has been","were"],"answer_index":0,"explanation_cn":"过去被动 = was + 过去分词。✓ The tree was planted near the church fifty years ago.\n✗ is:时态应是过去;✗ has been:此处强调过去某时的动作;✗ were:主语单数不用 were。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',7,NULL,'cloze','{"stem":"第 3 空","context":"The tiny village of Frinley ___1___ said to possess a ''cursed tree''. The tree ___2___ planted near the church fifty years ago. The vicar ___3___ asked to have it cut down, but he refused. So far, not one tourist ___4___ struck down by sudden death.","blank_no":3,"options":["has been","is being","was","has"],"answer_index":0,"explanation_cn":"现在完成被动 = has been + 过去分词。✓ The vicar has been asked to have it cut down.\n✗ is being:进行被动;✗ was:过去;✗ has:少了 been。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',7,NULL,'cloze','{"stem":"第 4 空","context":"The tiny village of Frinley ___1___ said to possess a ''cursed tree''. The tree ___2___ planted near the church fifty years ago. The vicar ___3___ asked to have it cut down, but he refused. So far, not one tourist ___4___ struck down by sudden death.","blank_no":4,"options":["has been","is being","was","has"],"answer_index":0,"explanation_cn":"现在完成被动 = has been + 过去分词;\"至今没被击倒\"。✓ not one tourist has been struck down.\n✗ is being:进行被动;✗ was:过去;✗ has:少了 been。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',8,NULL,'choice','{"stem":"Why has the number of visitors to Frinley increased?","options":["Because of a new hotel","Because of a festival","Because of cheap trains","Because the ''cursed tree'' was mentioned in a newspaper"],"answer_index":3,"explanation_cn":"课文说 Because the tree was mentioned in a newspaper, the number of visitors has now increased。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',8,NULL,'choice','{"stem":"What do villagers believe about the tree?","options":["If you touch it you''ll have bad luck; if you pick a leaf you''ll die","It brings rain","It grants wishes","It cures illness"],"answer_index":0,"explanation_cn":"课文说 if anyone touches the tree, he will have bad luck; if he picks a leaf, he will die。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',8,NULL,'choice','{"stem":"Why won''t the vicar cut down the tree?","options":["It is too big","It is a useful source of income from tourists","He is afraid of the curse","It is protected by law"],"answer_index":1,"explanation_cn":"课文说 the tree is a useful source of income, as tourists have been coming to see it。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',9,NULL,'choice','{"stem":"你想说\"你的钱包被找到了\"(已被…用现在完成被动 has been done):","options":["Your wallet has found.","Your wallet is finding.","Your wallet has been found.","Your wallet has being found."],"answer_index":2,"explanation_cn":"现在完成被动 = has been + 过去分词(find→found)。✓ Your wallet has been found. 场合:说某物已经被(人)找到了。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',9,NULL,'choice','{"stem":"你想说\"据说他是个天才\"(据说…用 be said to be):","options":["He is said be a genius.","He is said to be a genius.","He is say to be a genius.","He said to be a genius."],"answer_index":1,"explanation_cn":"be said to be 表\"据说是…\"。✓ He is said to be a genius. 场合:转述别人对某人的说法。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',9,NULL,'choice','{"stem":"你想说\"牧师被请求把这棵树砍掉\"(让某物被…用 have sth done):","options":["The vicar was asked to have the tree to cut down.","The vicar was asked to have the tree cut it down.","The vicar was asked to have the tree cutting down.","The vicar was asked to have the tree cut down."],"answer_index":3,"explanation_cn":"have sth done 表\"让某物被…\";the tree 与 cut 是被动关系,用过去分词 cut down。✓ The vicar was asked to have the tree cut down. 场合:请人把某物(叫别人)处理掉。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',10,NULL,'choice','{"stem":"possess 的意思是:","options":["出售","隐藏","失去","拥有"],"answer_index":3,"explanation_cn":"possess = 拥有。✓ said to possess a cursed tree 据说有一棵被诅咒的树。\n顺带记:失去 = lose;出售 = sell;隐藏 = hide."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',10,NULL,'choice','{"stem":"income 的意思是:","options":["收入","礼物","债务","支出"],"answer_index":0,"explanation_cn":"income = 收入。✓ a useful source of income 一个有用的财源。\n顺带记:支出 = expense;债务 = debt;礼物 = gift."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',10,NULL,'choice','{"stem":"\"The tree ___ planted fifty years ago.\"(过去被动)","options":["is","were","has","was"],"answer_index":3,"stem_cn":"这棵树是 50 年前栽的。","explanation_cn":"过去被动 = was + 过去分词。✓ The tree was planted fifty years ago.\n✗ is:时态应是过去;✗ has:构不成被动;✗ were:主语单数不用 were。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',10,NULL,'choice','{"stem":"\"So far, not one ___ struck down by sudden death.\"(现在完成被动)","options":["has","has been","was","is being"],"answer_index":1,"stem_cn":"到目前为止还没一个人暴死。","explanation_cn":"现在完成被动 = has been + 过去分词。✓ not one has been struck down by sudden death.\n✗ is being:进行被动;✗ was:过去;✗ has:少了 been。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',10,NULL,'choice','{"stem":"\"a blessing in disguise\" 的意思是:","options":["一个惊喜","一份礼物","彻头彻尾的坏事","因祸得福,坏事变好事"],"answer_index":3,"explanation_cn":"a blessing in disguise = 因祸得福、坏事变好事(表面是坏事,结果反而是好事)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',10,NULL,'choice','{"stem":"\"so far\" 的意思是:","options":["早晚","非常","到目前为止","很远"],"answer_index":2,"explanation_cn":"so far = 到目前为止、迄今。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',10,NULL,'choice','{"stem":"What harm has the ''cursed tree'' actually done to tourists?","options":["None — so far not one has been struck down","Some were injured","Many have fallen ill","Several have died"],"answer_index":0,"passage":"The tiny village of Frinley is said to possess a ''cursed tree''. Because the tree was mentioned in a newspaper, the number of visitors to Frinley has now increased. The tree was planted near the church fifty years ago, but it is only in recent years that it has gained an evil reputation. It is said that if anyone touches the tree, he will have bad luck; if he picks a leaf, he will die. Many villagers believe that the tree has already claimed a number of victims. The vicar has been asked to have the tree cut down, but so far he has refused. He has pointed out that the tree is a useful source of income, as tourists have been coming from all parts of the country to see it. In spite of all that has been said, the tourists have been picking leaves and cutting their names on the tree-trunk. So far, not one of them has been struck down by sudden death!","explanation_cn":"课文说 So far, not one of them has been struck down by sudden death,其实没造成任何伤害。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',10,NULL,'choice','{"stem":"Why is the tree a ''blessing in disguise'' for the village?","options":["It gives free fruit","It provides shade","It purifies the air","The tourists it draws are a useful source of income"],"answer_index":3,"passage":"The tiny village of Frinley is said to possess a ''cursed tree''. Because the tree was mentioned in a newspaper, the number of visitors to Frinley has now increased. The tree was planted near the church fifty years ago, but it is only in recent years that it has gained an evil reputation. It is said that if anyone touches the tree, he will have bad luck; if he picks a leaf, he will die. Many villagers believe that the tree has already claimed a number of victims. The vicar has been asked to have the tree cut down, but so far he has refused. He has pointed out that the tree is a useful source of income, as tourists have been coming from all parts of the country to see it. In spite of all that has been said, the tourists have been picking leaves and cutting their names on the tree-trunk. So far, not one of them has been struck down by sudden death!","explanation_cn":"课文说 the tree is a useful source of income, as tourists have been coming to see it,游客带来收入。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',10,NULL,'choice','{"stem":"What do tourists do to the tree despite the warnings?","options":["Water it","Pick leaves and cut their names on the trunk","Pray to it","Only photograph it"],"answer_index":1,"audio":"The tiny village of Frinley is said to possess a ''cursed tree''. Because the tree was mentioned in a newspaper, the number of visitors to Frinley has now increased. The tree was planted near the church fifty years ago, but it is only in recent years that it has gained an evil reputation. It is said that if anyone touches the tree, he will have bad luck; if he picks a leaf, he will die. Many villagers believe that the tree has already claimed a number of victims. The vicar has been asked to have the tree cut down, but so far he has refused. He has pointed out that the tree is a useful source of income, as tourists have been coming from all parts of the country to see it. In spite of all that has been said, the tourists have been picking leaves and cutting their names on the tree-trunk. So far, not one of them has been struck down by sudden death!","explanation_cn":"课文说 the tourists have been picking leaves and cutting their names on the tree-trunk。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l58',10,NULL,'choice','{"stem":"Has anyone actually died from touching the tree?","options":["Yes, a few","Yes, many","The text doesn''t say","No, not one has been struck down"],"answer_index":3,"audio":"The tiny village of Frinley is said to possess a ''cursed tree''. Because the tree was mentioned in a newspaper, the number of visitors to Frinley has now increased. The tree was planted near the church fifty years ago, but it is only in recent years that it has gained an evil reputation. It is said that if anyone touches the tree, he will have bad luck; if he picks a leaf, he will die. Many villagers believe that the tree has already claimed a number of victims. The vicar has been asked to have the tree cut down, but so far he has refused. He has pointed out that the tree is a useful source of income, as tourists have been coming from all parts of the country to see it. In spite of all that has been said, the tourists have been picking leaves and cutting their names on the tree-trunk. So far, not one of them has been struck down by sudden death!","explanation_cn":"课文说 So far, not one of them has been struck down by sudden death,没有人因此死去。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l59',2,8,59,'In or out?','进来还是出去?','Review KS50-58 时态综合复习(一般现在/过去、现在完成/完成进行、would·used to 过去习惯、被动语态/is said to 转述被动)(教材 L59 Key structures)主考;SD 表目的的多种方式(to/in order to/so as to/so that/in order that)+ 课文 every time、so…that、become an expert at(辅考)','我家的狗雷克斯,过去常坐在大门外面叫。每当它想到院子里来时,便汪汪叫个不停,直到有人把门打开。由于邻居们对狗叫很有意见,所以我丈夫花了几个星期的时间训练它用脚爪按住门闩把自己放进来。雷克斯很快成了开门的专家。然而上星期我正要出去买东西时,发现它正呆在院子里边挨门的地方。这次它叫着让人把它放出去!从那以后,它养成了另外一种坏习惯。它从外面把门一打开,就走进院子,等着门自动关上。这之后它就坐下汪汪叫起来,直到有人来把它放出去。出去之后,它又马上把自己放进来,接着再开始叫。昨天,我丈夫把大门卸了下来,雷克斯很生气,此后我们便再也没有见到它。','{"q":"Listen and answer — Why did Rex run away?","options":["He got so annoyed when his owner removed the gate","He found a bigger yard","He was afraid of the neighbors","He chased a cat and got lost"],"answer_index":0}'::jsonb,'{"title":"时态综合复习(KS50-58)","intro":"复习第 50-58 课的时态与句型:一般现在(经常/习惯 barks)、一般过去(complained)、现在完成(has developed)、现在完成进行(have been coming)、would/used to(过去习惯)、被动语态(was trained / is said to)。根据时间标志和语境选对时态。","table":{"headers":["时态/句型","例子"],"rows":[["一般现在(习惯)","Every time he wants in, he barks."],["一般过去","My husband removed the gate."],["现在完成","he has developed a bad habit."],["过去习惯 would/used to","Rex used to sit and bark."],["被动 / 转述被动","The dog was trained. / is said to…"]]},"specialRules":[{"rule":"SD 表目的的多种方式:to do、in order to do、so as (not) to do、so that + 从句、in order that + 从句、for sb to do。","mark":"表目的多方式"},{"rule":"every time 作连词''每当'';so … that 表''如此…以致…''(that 可省略);become an expert at doing。","mark":"课文连词/搭配"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l59',1,NULL,'Our dog, Rex, used to sit outside our front gate and bark. Every time he wanted to come into the yard he would bark until someone opened the gate.','我家的狗雷克斯过去常坐在大门外面叫。每当它想到院子里来,便汪汪叫个不停,直到有人开门。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l59',2,NULL,'As the neighbors complained of the noise, my husband spent weeks training him to press his paw on the latch to let himself in.','由于邻居们对狗叫很有意见,我丈夫花了几个星期训练它用脚爪按门闩把自己放进来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l59',3,NULL,'Rex soon became an expert at opening the gate.','雷克斯很快成了开门的专家。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l59',4,NULL,'However, when I was going out shopping last week, I noticed him in the yard near the gate. This time he was barking so that someone would let him out!','然而上星期我正要出去买东西时,发现它正呆在院子里挨门的地方。这次它叫着让人把它放出去!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l59',5,NULL,'Since then, he has developed another bad habit.','从那以后,它养成了另外一种坏习惯。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l59',6,NULL,'As soon as he opens the gate from the outside, he comes into the yard and waits until the gate shuts. Then he sits and barks until someone lets him out.','它从外面把门一打开,就走进院子,等着门自动关上。然后坐下汪汪叫,直到有人把它放出去。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l59',7,NULL,'After this he immediately lets himself in and begins barking again.','出去之后,它又马上把自己放进来,接着再开始叫。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l59',8,NULL,'Yesterday my husband removed the gate and Rex got so annoyed we have not seen him since.','昨天我丈夫把大门卸了下来,雷克斯很生气,此后我们便再也没有见到它。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
