INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l59','line','queue','(排)队;美语 line,英式 queue') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l59','every time','',NULL,'/ˈevri taɪm/','Every time he wanted in, he barked.','每当它想进来就叫。','Every time I see her, she smiles.','每次见到她,她都微笑。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l59','so that','',NULL,'/soʊ ðæt/','He barked so that someone would let him out.','它叫是为了让人放它出去。','Speak loudly so that everyone can hear.','大声说,好让大家都听见。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l59','become an expert at','',NULL,'/ˈekspɜːrt æt/','Rex became an expert at opening the gate.','雷克斯成了开门的能手。','She became an expert at cooking.','她成了烹饪能手。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l59','develop a (bad) habit','',NULL,'/dɪˈveləp ə ˈhæbɪt/','He has developed another bad habit.','它又养成了个坏习惯。','Try not to develop bad habits.','尽量别养成坏习惯。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp1','choice','{"stem":"\"Every time he wants to come in, he ___ until someone opens the gate.\"(经常性习惯,用一般现在时)","options":["barks","is barking","barked","has barked"],"answer_index":0,"stem_cn":"每当它想进来,就叫个不停,直到有人开门。","explanation_cn":"\"每当…就…\"这种经常性、习惯性动作用一般现在时;主语 he 用 barks。✓ Every time he wants to come in, he barks. ✗ is barking:此处不是此刻正在进行;✗ barked:一般过去;✗ has barked:现在完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp1','choice','{"stem":"\"Yesterday my husband ___ the gate.\"(过去某时,remove 的过去式)","options":["is removing","removes","has removed","removed"],"answer_index":3,"stem_cn":"昨天我丈夫把大门卸了下来。","explanation_cn":"Yesterday 表明是过去某时的动作,用一般过去时;remove 的过去式是 removed。✓ Yesterday my husband removed the gate. ✗ removes:一般现在;✗ has removed:不与 yesterday 连用;✗ is removing:现在进行。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp1','choice','{"stem":"\"As the neighbors ___ of the noise, my husband trained the dog.\"(过去,complain 的过去式)","options":["complain","are complaining","complained","have complained"],"answer_index":2,"stem_cn":"由于邻居们抱怨噪音,我丈夫训练了狗。","explanation_cn":"叙述过去发生的原因用一般过去时;complain 的过去式是 complained。✓ As the neighbors complained of the noise… ✗ complain:一般现在;✗ have complained:现在完成;✗ are complaining:现在进行。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp2','choice','{"stem":"\"Since then, he ___ another bad habit.\"(现在完成时:已养成)","options":["has developed","is developing","developed","develops"],"answer_index":0,"stem_cn":"从那以后,它养成了另一个坏习惯。","explanation_cn":"Since then 表\"从那时起到现在\",用现在完成时。✓ Since then, he has developed another bad habit. ✗ developed:一般过去,不与 since then 连用;✗ is developing:现在进行;✗ develops:一般现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp2','choice','{"stem":"\"Rex got so annoyed that we ___ him since.\"(现在完成时:一直没见到)","options":["did not see","have not seen","do not see","are not seeing"],"answer_index":1,"stem_cn":"雷克斯很生气,此后我们再没见到它。","explanation_cn":"\"此后一直没见到\"用现在完成时(动作延续到现在);主语 we 用 have not seen。✓ we have not seen him since. ✗ did not see:一般过去;✗ are not seeing:现在进行;✗ do not see:一般现在。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp2','choice','{"stem":"\"Tourists ___ coming to see the tree for weeks.\"(现在完成进行时:一直在来)","options":["are","has been","have been","were"],"answer_index":2,"stem_cn":"游客们一连几周一直来看这棵树。","explanation_cn":"\"一连几周一直在来\"用现在完成进行时 have been + 现在分词;主语 tourists 复数用 have been。✓ Tourists have been coming to see the tree for weeks. ✗ are:现在进行不含\"几周一直\";✗ were:过去;✗ has been:主语复数不用 has。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp3','choice','{"stem":"\"Our dog ___ sit outside the gate and bark.\"(过去常做、现在不做了的习惯)","options":["used to","uses to","is used to","would be"],"answer_index":0,"stem_cn":"我家的狗过去常坐在门外叫。","explanation_cn":"\"过去常做、现在不做了\"的习惯用 used to + 动词原形。✓ Our dog used to sit outside the gate and bark. ✗ would be:构不成这个意思;✗ uses to:形式错;✗ is used to:意思是\"习惯于\"。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp3','choice','{"stem":"\"Every time he wanted to come in, he ___ bark until someone opened the gate.\"(过去反复动作)","options":["is","will","used to be","would"],"answer_index":3,"stem_cn":"每当它想进来,就会叫到有人开门为止。","explanation_cn":"过去反复、经常发生的动作用 would + 动词原形。✓ Every time he wanted to come in, he would bark. ✗ used to be:构不成这个意思;✗ will:将来;✗ is:构不成过去反复。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp4','choice','{"stem":"\"The dog ___ trained to press the latch.\"(过去被动:被训练)","options":["is","was","were","has"],"answer_index":1,"stem_cn":"这只狗被训练用爪子按门闩。","explanation_cn":"过去被动 = was + 过去分词;主语 dog 单数用 was trained。✓ The dog was trained to press the latch. ✗ is:时态应是过去;✗ has:构不成被动;✗ were:主语单数不用 were。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp4','choice','{"stem":"\"The village is ___ to possess a cursed tree.\"(转述被动:据说)","options":["said","saying","told","say"],"answer_index":0,"stem_cn":"据说这个村庄有一棵被诅咒的树。","explanation_cn":"be said to 表\"据说…\";此处填过去分词 said(is said to possess)。✓ The village is said to possess a cursed tree. ✗ say:原形;✗ saying:现在分词;✗ told:be told to 是\"被告知去做\",词义不同。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp4','choice','{"stem":"\"Your wallet ___ found.\"(现在完成被动:已被找到)","options":["has","has been","is being","was being"],"answer_index":1,"stem_cn":"你的钱包被找到了。","explanation_cn":"现在完成被动 = has been + 过去分词。✓ Your wallet has been found. ✗ is being:进行被动;✗ was being:过去进行被动;✗ has:少了 been。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp5','choice','{"stem":"\"He ran to the station ___ catch the train.\"(表目的,用不定式)","options":["for","so","that","to"],"answer_index":3,"stem_cn":"他跑到车站去赶火车。","explanation_cn":"表示目的最简单的方式是用不定式 to do。✓ He ran to the station to catch the train. ✗ for:后不接动词原形表目的;✗ so / that:单独不引导目的。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp5','choice','{"stem":"\"This time he was barking ___ that someone would let him out.\"(表目的''为的是'',引导从句的那个词)","options":["in","so","for","as"],"answer_index":1,"stem_cn":"这次它叫着,为的是让人把它放出去。","explanation_cn":"表目的\"为的是\"用 so that 引导从句,此处填 so。✓ He was barking so that someone would let him out. ✗ in:in that 不表目的;✗ for / as:不与 that 构成目的从句。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp5','choice','{"stem":"\"I opened the door quietly ___ as not to disturb him.\"(表目的否定''以免、免得''的第一个词)","options":["in","to","for","so"],"answer_index":3,"stem_cn":"我轻轻把门打开,为的是不打搅他。","explanation_cn":"表目的的否定\"以免、免得\"用 so as not to,此处填 so。✓ I opened the door quietly so as not to disturb him. ✗ in / for / to:不构成 so as not to 结构。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp5','choice','{"stem":"\"He works hard in ___ to pass his exams.\"(表目的''为了'',与 in…to 搭配的名词)","options":["that","order","case","so"],"answer_index":1,"stem_cn":"他学习刻苦,为的是通过考试。","explanation_cn":"表目的\"为了\"用 in order to,与 in…to 搭配的名词是 order。✓ He works hard in order to pass his exams. ✗ that:in order that 后接从句不接 to;✗ so / case:不构成 in…to 结构。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp6','choice','{"stem":"\"___ time he wanted to come in, he barked.\"(每当…,作时间连词)","options":["Some","Any","Every","No"],"answer_index":2,"stem_cn":"每当它想进来,就叫。","explanation_cn":"every time 作连词,表\"每当、无论何时\",引导时间状语从句。✓ Every time he wanted to come in, he barked. ✗ Some / Any / No:不与 time 构成\"每当\"的连词。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp6','choice','{"stem":"\"Rex got ___ annoyed that we have not seen him since.\"(如此…以致…的前一个词)","options":["so","very","such","too"],"answer_index":0,"stem_cn":"雷克斯很生气,此后我们再没见到它。","explanation_cn":"\"如此…以致…\"用 so + 形容词 + that(that 可省略),此处填 so。✓ Rex got so annoyed (that) we have not seen him since. ✗ such:后接形容词时用 so;✗ too / very:不与 that 从句构成\"如此…以致…\"。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',5,'am2_l59_gp6','choice','{"stem":"\"Rex soon became an expert ___ opening the gate.\"(''成为…能手''后接的介词)","options":["of","in","on","at"],"answer_index":3,"stem_cn":"雷克斯很快成了开门的专家。","explanation_cn":"become an expert at (doing) sth 表\"成为…的能手\";介词用 at。✓ Rex became an expert at opening the gate. ✗ in / on / of:不与 expert 这样搭配表\"擅长做…\"。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',6,NULL,'choice','{"stem":"美语里\"(房子的)院子\"常说:","options":["grass area","garden","yard","lawn plot"],"answer_index":2,"explanation_cn":"美语\"(房子的)院子\"常说 yard;英式说 garden。✓ play in the yard 在院子里玩。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',6,NULL,'choice','{"stem":"美语拼写\"邻居\"是:","options":["neighbor","neighbour","neighber","naybor"],"answer_index":0,"explanation_cn":"美语拼写\"邻居\"是 neighbor(英式 neighbour)。✓ a friendly neighbor 一个友好的邻居。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',6,NULL,'choice','{"stem":"bark 的意思是:","options":["跑","咬","(狗)叫,吠","跳"],"answer_index":2,"explanation_cn":"bark = (狗)叫、吠。✓ sit outside and bark 坐在外面叫。\n顺带记:跑 = run;跳 = jump;咬 = bite."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',6,NULL,'choice','{"stem":"expert 的意思是:","options":["专家,能手","新手","顾客","学生"],"answer_index":0,"explanation_cn":"expert = 专家、能手。✓ an expert at opening the gate 开门的能手。\n顺带记:新手 = beginner;学生 = student;顾客 = customer."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',6,NULL,'choice','{"stem":"develop 的意思是:","options":["忘记","破坏","养成;发展","隐藏"],"answer_index":2,"explanation_cn":"develop = 养成(习惯);发展。✓ developed another bad habit 养成了另一个坏习惯。\n顺带记:破坏 = destroy;忘记 = forget;隐藏 = hide."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',6,NULL,'choice','{"stem":"remove 的意思是:","options":["拆掉,移开,取下","修理","购买","安装"],"answer_index":0,"explanation_cn":"remove = 拆掉、移开、取下。✓ removed the gate 把大门卸了下来。\n顺带记:安装 = install;修理 = mend;购买 = buy."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',7,NULL,'cloze','{"stem":"第 1 空","context":"Our dog Rex ___1___ sit outside our gate and bark. Every time he wanted in, he ___2___ bark until someone opened the gate. My husband ___3___ weeks training him. Since then, he ___4___ another bad habit.","blank_no":1,"options":["used to","would be","uses to","is used to"],"answer_index":0,"explanation_cn":"\"过去常做、现在不做了\"的习惯用 used to + 动词原形。✓ Our dog Rex used to sit outside our gate and bark.\n✗ would be:构不成这个意思;✗ uses to:形式错;✗ is used to:意思是\"习惯于\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',7,NULL,'cloze','{"stem":"第 2 空","context":"Our dog Rex ___1___ sit outside our gate and bark. Every time he wanted in, he ___2___ bark until someone opened the gate. My husband ___3___ weeks training him. Since then, he ___4___ another bad habit.","blank_no":2,"options":["would","will","is","has"],"answer_index":0,"explanation_cn":"过去反复动作(每次都叫)用 would + 动词原形。✓ Every time he wanted in, he would bark.\n✗ will:将来;✗ is / has:构不成过去反复。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',7,NULL,'cloze','{"stem":"第 3 空","context":"Our dog Rex ___1___ sit outside our gate and bark. Every time he wanted in, he ___2___ bark until someone opened the gate. My husband ___3___ weeks training him. Since then, he ___4___ another bad habit.","blank_no":3,"options":["spent","spends","has spent","is spending"],"answer_index":0,"explanation_cn":"过去某时的动作用一般过去时;spend 的过去式是 spent。✓ My husband spent weeks training him.\n✗ spends:一般现在;✗ has spent:现在完成;✗ is spending:现在进行。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',7,NULL,'cloze','{"stem":"第 4 空","context":"Our dog Rex ___1___ sit outside our gate and bark. Every time he wanted in, he ___2___ bark until someone opened the gate. My husband ___3___ weeks training him. Since then, he ___4___ another bad habit.","blank_no":4,"options":["has developed","developed","is developing","develops"],"answer_index":0,"explanation_cn":"Since then 表\"从那时起到现在\",用现在完成时。✓ Since then, he has developed another bad habit.\n✗ developed:一般过去,不与 since then 连用;✗ is developing:现在进行;✗ develops:一般现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',8,NULL,'choice','{"stem":"What did Rex used to do at the front gate?","options":["Sit outside and bark until someone opened it","Dig under it","Guard it silently","Sleep beside it"],"answer_index":0,"explanation_cn":"课文说 Rex used to sit outside our front gate and bark… until someone opened the gate。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',8,NULL,'choice','{"stem":"What did the husband train Rex to do?","options":["Fetch the newspaper","Open the door with his mouth","Press his paw on the latch to let himself in","Stop barking"],"answer_index":2,"explanation_cn":"课文说 my husband spent weeks training him to press his paw on the latch to let himself in。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',8,NULL,'choice','{"stem":"Why did Rex disappear at the end?","options":["He chased a cat","He got so annoyed when the gate was removed","He was afraid of the husband","He found a new home"],"answer_index":1,"explanation_cn":"课文说 my husband removed the gate and Rex got so annoyed we have not seen him since。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',9,NULL,'choice','{"stem":"你想说\"我家的狗过去常坐在门外叫\"(过去习惯用 used to):","options":["Our dog used to sit outside the gate and bark.","Our dog use to sit outside the gate and bark.","Our dog is used to sit outside the gate and bark.","Our dog used to sitting outside the gate and bark."],"answer_index":0,"explanation_cn":"\"过去常做、现在不做了\"的习惯用 used to + 动词原形。✓ Our dog used to sit outside the gate and bark. 场合:说过去经常做、现在已不做的事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',9,NULL,'choice','{"stem":"你想说\"它叫着,为的是让人放它出去\"(表目的用 so that):","options":["He was barking so as someone would let him out.","He was barking in that someone would let him out.","He was barking so that someone would let him out.","He was barking for that someone would let him out."],"answer_index":2,"explanation_cn":"表目的\"为的是\"用 so that + 从句。✓ He was barking so that someone would let him out. 场合:说做某事是为了达到某目的。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',9,NULL,'choice','{"stem":"你想说\"从那以后它养成了另一个坏习惯\"(现在完成用 has done):","options":["Since then, he develops another bad habit.","Since then, he has developed another bad habit.","Since then, he is developing another bad habit.","Since then, he developed another bad habit."],"answer_index":1,"explanation_cn":"Since then 表\"从那时起到现在\",用现在完成时。✓ Since then, he has developed another bad habit. 场合:说从过去某时到现在发生的变化。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',10,NULL,'choice','{"stem":"bark 的意思是:","options":["跑","(狗)叫,吠","咬","跳"],"answer_index":1,"explanation_cn":"bark = (狗)叫、吠。✓ sit outside and bark 坐在外面叫。\n顺带记:跑 = run;跳 = jump;咬 = bite."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',10,NULL,'choice','{"stem":"expert 的意思是:","options":["专家,能手","学生","新手","顾客"],"answer_index":0,"explanation_cn":"expert = 专家、能手。✓ an expert at opening the gate 开门的能手。\n顺带记:新手 = beginner;学生 = student;顾客 = customer."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',10,NULL,'choice','{"stem":"\"Every time he wants in, he ___ until someone opens the gate.\"(经常性习惯,一般现在时)","options":["is barking","barked","has barked","barks"],"answer_index":3,"stem_cn":"每当它想进来,就叫到有人开门。","explanation_cn":"\"每当…就…\"的经常性习惯用一般现在时。✓ Every time he wants in, he barks until someone opens the gate.\n✗ is barking:不是此刻进行;✗ barked:一般过去;✗ has barked:现在完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',10,NULL,'choice','{"stem":"\"Since then, he ___ another bad habit.\"(现在完成时)","options":["has developed","develops","developed","is developing"],"answer_index":0,"stem_cn":"从那以后它养成了另一个坏习惯。","explanation_cn":"Since then 表\"从那时起到现在\",用现在完成时。✓ Since then, he has developed another bad habit.\n✗ developed:一般过去;✗ is developing:现在进行;✗ develops:一般现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',10,NULL,'choice','{"stem":"\"every time\" 作连词的意思是:","options":["立刻","有时","从不","每当,每次"],"answer_index":3,"explanation_cn":"every time 作连词 = 每当、每次、无论何时。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',10,NULL,'choice','{"stem":"\"become an expert at\" 的意思是:","options":["害怕…","成为…的能手/专家","对…感到厌倦","放弃…"],"answer_index":1,"explanation_cn":"become an expert at (doing) sth = 成为…的能手、擅长做某事。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',10,NULL,'choice','{"stem":"How did Rex learn to let himself in?","options":["The husband trained him to press the latch with his paw","He watched the neighbors do it","He broke the gate open","He was born knowing how"],"answer_index":0,"passage":"Our dog, Rex, used to sit outside our front gate and bark. Every time he wanted to come into the yard he would bark until someone opened the gate. As the neighbors complained of the noise, my husband spent weeks training him to press his paw on the latch to let himself in. Rex soon became an expert at opening the gate. However, when I was going out shopping last week, I noticed him in the yard near the gate. This time he was barking so that someone would let him out! Since then, he has developed another bad habit. As soon as he opens the gate from the outside, he comes into the yard and waits until the gate shuts. Then he sits and barks until someone lets him out. After this he immediately lets himself in and begins barking again. Yesterday my husband removed the gate and Rex got so annoyed we have not seen him since.","explanation_cn":"课文说 my husband spent weeks training him to press his paw on the latch to let himself in。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',10,NULL,'choice','{"stem":"What new bad habit did Rex develop?","options":["Running away every day","Barking only at cats","Chewing the gate","Letting himself out, then barking to be let in again, over and over"],"answer_index":3,"passage":"Our dog, Rex, used to sit outside our front gate and bark. Every time he wanted to come into the yard he would bark until someone opened the gate. As the neighbors complained of the noise, my husband spent weeks training him to press his paw on the latch to let himself in. Rex soon became an expert at opening the gate. However, when I was going out shopping last week, I noticed him in the yard near the gate. This time he was barking so that someone would let him out! Since then, he has developed another bad habit. As soon as he opens the gate from the outside, he comes into the yard and waits until the gate shuts. Then he sits and barks until someone lets him out. After this he immediately lets himself in and begins barking again. Yesterday my husband removed the gate and Rex got so annoyed we have not seen him since.","explanation_cn":"课文说它自己开门进院子、叫着让人放出去、又马上把自己放进来、再叫,反复循环。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',10,NULL,'choice','{"stem":"Why did the neighbors complain?","options":["Loud music","Rex''s barking noise","A broken gate","The husband''s shouting"],"answer_index":1,"audio":"Our dog, Rex, used to sit outside our front gate and bark. Every time he wanted to come into the yard he would bark until someone opened the gate. As the neighbors complained of the noise, my husband spent weeks training him to press his paw on the latch to let himself in. Rex soon became an expert at opening the gate. However, when I was going out shopping last week, I noticed him in the yard near the gate. This time he was barking so that someone would let him out! Since then, he has developed another bad habit. As soon as he opens the gate from the outside, he comes into the yard and waits until the gate shuts. Then he sits and barks until someone lets him out. After this he immediately lets himself in and begins barking again. Yesterday my husband removed the gate and Rex got so annoyed we have not seen him since.","explanation_cn":"课文说 the neighbors complained of the noise,指的是 Rex 汪汪叫的声音。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l59',10,NULL,'choice','{"stem":"What happened after the gate was removed?","options":["Nothing changed","Rex was happy","Rex got so annoyed he disappeared","Rex learned a new trick"],"answer_index":2,"audio":"Our dog, Rex, used to sit outside our front gate and bark. Every time he wanted to come into the yard he would bark until someone opened the gate. As the neighbors complained of the noise, my husband spent weeks training him to press his paw on the latch to let himself in. Rex soon became an expert at opening the gate. However, when I was going out shopping last week, I noticed him in the yard near the gate. This time he was barking so that someone would let him out! Since then, he has developed another bad habit. As soon as he opens the gate from the outside, he comes into the yard and waits until the gate shuts. Then he sits and barks until someone lets him out. After this he immediately lets himself in and begins barking again. Yesterday my husband removed the gate and Rex got so annoyed we have not seen him since.","explanation_cn":"课文说 my husband removed the gate and Rex got so annoyed we have not seen him since。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
